// --- CONSTANTES DE NEGOCIO (Cap. 3) ---
const MAX_CONSECUTIVE_EVENTS = 3; // ¡Este es nuestro valor N!
const MAX_TEMP = 8.0;
const MAX_G_FORCE = 2.5;

// --- DATOS DE ENTRADA ---
let data = msg.payload;

// --- LÓGICA DE VALIDACIÓN (Cap. 2 - igual que antes) ---
if (!data.hasOwnProperty('temperatura') || 
    !data.hasOwnProperty('fuerza_g') || 
    !data.hasOwnProperty('id_paquete') ||
    !data.hasOwnProperty('timestamp') ||
    typeof data.temperatura !== 'number') {

    node.error("Error: JSON inválido o campos/tipos incorrectos", msg);
    return null; // Detiene el flujo
}

// --- LÓGICA DE MEMORIA (STATEFUL) (Cap. 3) ---

// 1. Carga la "memoria" (el objeto con los contadores de cada paquete)
//    Si no existe, crea un objeto vacío {}.
let packageState = flow.get("packageState") || {};

let packageID = data.id_paquete;
let isAlert = false;

// 2. Inicializa la memoria para este paquete si es la primera vez que lo vemos
if (!packageState[packageID]) {
    packageState[packageID] = {
        consecutiveTempAlerts: 0,
        consecutiveForceAlerts: 0
    };
    node.log("Nuevo paquete detectado: " + packageID);
}

// 3. REGLA DE NEGOCIO: Comprueba si hay una condición de alerta
if (data.temperatura > MAX_TEMP || data.fuerza_g > MAX_G_FORCE) {
    // Si la temperatura es alta...
    if (data.temperatura > MAX_TEMP) {
        packageState[packageID].consecutiveTempAlerts++; // Incrementa el contador de temperatura
    }
    // Si la fuerza_g es alta...
    if (data.fuerza_g > MAX_G_FORCE) {
        packageState[packageID].consecutiveForceAlerts++; // Incrementa el contador de fuerza_g
    }

    node.warn(`¡Pre-Alerta! Paquete ${packageID} con valores anómalos.`);

} else {
    // Si el dato es NORMAL, reseteamos los contadores a 0.
    // Esto asegura que solo contamos eventos ANÓMALOS *CONSECUTIVOS*.
    packageState[packageID].consecutiveTempAlerts = 0;
    packageState[packageID].consecutiveForceAlerts = 0;
}

// 4. Guarda la memoria actualizada
flow.set("packageState", packageState);

// 5. DECISIÓN: ¿Disparamos la alerta?
// Comprobamos si alguno de los contadores ha alcanzado nuestro límite N (3)
if (packageState[packageID].consecutiveTempAlerts >= MAX_CONSECUTIVE_EVENTS ||
    packageState[packageID].consecutiveForceAlerts >= MAX_CONSECUTIVE_EVENTS) {

    isAlert = true;

    // (Opcional) Reseteamos el contador para que no envíe 100 alertas,
    // sino solo una cuando se cumple la condición.
    packageState[packageID].consecutiveTempAlerts = 0; 
    packageState[packageID].consecutiveForceAlerts = 0;
}

// --- SALIDA ---

// Añadimos la nueva información al mensaje
msg.isAlert = isAlert; 
msg.packageState = packageState[packageID]; // (Para depurar)

// Dejamos pasar el mensaje (ya sea alerta o no) al siguiente nodo (la API)
return msg;
